import json
import os
import glob

CHECKPOINT_ROOT = "/root/autodl-tmp/exp001/checkpoints"
OUTPUT_DIR = "/root/contamcal-irt-calibration/artifacts/training_curves"

FAMILY_MAP = {
    "phi-4": "Phi-4",
    "Qwen2.5-14B": "Qwen-14B",
    "Qwen2.5-7B": "Qwen-7B",
    "gemma-2-9b": "Gemma-2",
    "OLMo-2-7B": "OLMo-2",
}

DOSAGES = ["d000", "d005", "d025", "d050", "d100"]
SEEDS = ["s0", "s42", "s123"]

def parse_dir_name(dirname):
    for model_key in sorted(FAMILY_MAP.keys(), key=len, reverse=True):
        if dirname.startswith(model_key + "_"):
            rest = dirname[len(model_key) + 1:]
            parts = rest.split("_")
            if len(parts) == 2:
                dosage, seed = parts
                if dosage in DOSAGES and seed in SEEDS:
                    return FAMILY_MAP[model_key], dosage, seed
    return None, None, None

def extract_curves(trainer_state_path):
    with open(trainer_state_path) as f:
        state = json.load(f)

    curves = []
    for entry in state.get("log_history", []):
        if "loss" in entry and "step" in entry:
            curves.append({
                "step": entry["step"],
                "loss": round(entry["loss"], 6),
                "epoch": round(entry.get("epoch", 0), 4),
                "lr": entry.get("learning_rate", None),
                "mean_token_accuracy": round(entry.get("mean_token_accuracy", 0), 6) if "mean_token_accuracy" in entry else None,
            })
    return curves

def main():
    os.makedirs(OUTPUT_DIR, exist_ok=True)

    results = {}
    found = 0
    missing = []

    trainer_states = glob.glob(
        os.path.join(CHECKPOINT_ROOT, "*/lora_adapter/checkpoint-*/trainer_state.json")
    )

    for ts_path in trainer_states:
        dirname = ts_path.split("/checkpoints/")[1].split("/")[0]
        family, dosage, seed = parse_dir_name(dirname)
        if family is None:
            print(f"SKIP: {dirname}")
            continue

        curves = extract_curves(ts_path)
        if not curves:
            print(f"EMPTY: {dirname}")
            continue

        results.setdefault(family, {}).setdefault(dosage, {})[seed] = curves
        found += 1

    for family_name in FAMILY_MAP.values():
        for d in DOSAGES:
            for s in SEEDS:
                if family_name not in results or d not in results[family_name] or s not in results[family_name][d]:
                    missing.append(f"{family_name}/{d}/{s}")

    output_path = os.path.join(OUTPUT_DIR, "training_curves_data.json")
    with open(output_path, "w") as f:
        json.dump(results, f, indent=2)

    print(f"\nExtracted: {found}/75 combinations")
    print(f"Missing ({len(missing)}):")
    for m in missing:
        print(f"  - {m}")

    for family_name in sorted(results.keys()):
        for d in sorted(results[family_name].keys()):
            for s in sorted(results[family_name][d].keys()):
                curve = results[family_name][d][s]
                first_loss = curve[0]["loss"]
                last_loss = curve[-1]["loss"]
                n_steps = len(curve)
                trend = "OK" if last_loss < first_loss else "WARN_NO_DECREASE"
                print(f"  {family_name}/{d}/{s}: {n_steps} pts, {first_loss:.4f} -> {last_loss:.4f} [{trend}]")

    print(f"\nSaved to: {output_path}")

if __name__ == "__main__":
    main()
PYEOF
